# 通用页脚区块模板

## 结构

```
┌──────────────────────────────────────────┐
│ Logo + 简介                               │
├──────────┬──────────┬──────────┬─────────┤
│ 产品     │ 资源     │ 公司     │ 社交    │
│ 链接1    │ 链接1    │ 链接1    │ 图标1   │
│ 链接2    │ 链接2    │ 链接2    │ 图标2   │
│ 链接3    │ 链接3    │ 链接3    │ 图标3   │
├──────────┴──────────┴──────────┴─────────┤
│ © 2024 Company. All rights reserved.      │
└──────────────────────────────────────────┘
```

## 代码骨架

```tsx
const Footer: React.FC = () => {
  const columns = [
    { title: '产品', links: ['功能', '定价', '更新日志', '路线图'] },
    { title: '资源', links: ['文档', 'API', '社区', '博客'] },
    { title: '公司', links: ['关于', '招贤', '联系', '品牌'] },
  ];

  return (
    <footer style={{
      background: 'var(--color-bg-muted)',
      padding: 'var(--spacing-12) var(--spacing-4) var(--spacing-6)',
    }}>
      <div style={{ maxWidth: 1200, marginInline: 'auto' }}>
        <div style={{
          display: 'grid',
          gridTemplateColumns: '2fr repeat(3, 1fr)',
          gap: 'var(--spacing-8)',
        }}>
          {/* Logo + 简介 */}
          <div>
            <div className="footer-logo">Logo</div>
            <p style={{ color: 'var(--color-text-secondary)', marginTop: 'var(--spacing-2)' }}>
              一句话描述产品
            </p>
          </div>
          {/* 链接列 */}
          {columns.map(col => (
            <div key={col.title}>
              <h4>{col.title}</h4>
              <ul style={{ listStyle: 'none', padding: 0, marginTop: 'var(--spacing-2)' }}>
                {col.links.map(link => (
                  <li key={link}><a href="#">{link}</a></li>
                ))}
              </ul>
            </div>
          ))}
        </div>
        <div style={{
          borderTop: '1px solid var(--color-border-default)',
          marginTop: 'var(--spacing-8)',
          paddingTop: 'var(--spacing-4)',
          color: 'var(--color-text-muted)',
          fontSize: 'var(--font-size-sm)',
        }}>
          © 2024 Company. All rights reserved.
        </div>
      </div>
    </footer>
  );
};

export default Footer;
```

# 通用导航区块模板

## 桌面端导航

```
┌──────────────────────────────────────────┐
│ Logo  首页 产品 关于  [登录] [免费开始]  │
└──────────────────────────────────────────┘
```

## 移动端导航

```
┌──────────────────────┐
│ Logo          [☰]    │
└──────────────────────┘
```

## 代码骨架

```tsx
import React, { useState, useEffect } from 'react';

const Navigation: React.FC = () => {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header className={`nav ${scrolled ? 'nav-scrolled' : ''}`}>
      <div className="nav-container">
        <a className="nav-logo" href="/">Logo</a>

        {/* 桌面端链接 */}
        <nav className="nav-links">
          <a href="#features">特性</a>
          <a href="#pricing">定价</a>
          <a href="#about">关于</a>
        </nav>

        <div className="nav-actions">
          <button className="btn btn-ghost">登录</button>
          <button className="btn btn-primary">免费开始</button>
        </div>

        {/* 移动端汉堡菜单 */}
        <button className="nav-hamburger" onClick={() => setMenuOpen(!menuOpen)}>
          ☰
        </button>
      </div>

      {/* 移动端菜单 */}
      {menuOpen && (
        <div className="nav-mobile-menu">
          <a href="#features">特性</a>
          <a href="#pricing">定价</a>
          <a href="#about">关于</a>
          <button className="btn btn-primary">免费开始</button>
        </div>
      )}
    </header>
  );
};

export default Navigation;
```

## 关键样式

```css
.nav {
  position: fixed;
  top: 0;
  width: 100%;
  z-index: 100;
  transition: background var(--duration-base) var(--easing-standard);
}

/* 透明导航（滚动后变实色） */
.nav { background: transparent; }
.nav-scrolled { background: var(--color-bg-base); box-shadow: var(--shadow-sm); }

/* 移动端隐藏桌面链接 */
@media (max-width: 768px) {
  .nav-links, .nav-actions { display: none; }
  .nav-hamburger { display: block; }
}
```

