# 仪表盘模板

## 页面结构

```
┌─────────────────────────────────────────────┐
│ 面包屑                                       │
├─────────────────────────────────────────────┤
│ 数据概览                        日期筛选 ▼   │
├─────────────────────────────────────────────┤
│ ┌──────┐ ┌──────┐ ┌──────┐ ┌──────┐        │
│ │ 总数 │ │进行中│ │已完成│ │ 增长 │        │
│ │ 1128 │ │ 326  │ │ 678  │ │ 12%↑ │        │
│ └──────┘ └──────┘ └──────┘ └──────┘        │
│                                             │
│ ┌─────────────────────┐ ┌─────────────────┐ │
│ │ 趋势图              │ │ 分类统计        │ │
│ │                     │ │                 │ │
│ │                     │ │                 │ │
│ └─────────────────────┘ └─────────────────┘ │
│                                             │
│ ┌─────────────────────────────────────────┐ │
│ │ 最近动态 / 待办事项                     │ │
│ └─────────────────────────────────────────┘ │
└─────────────────────────────────────────────┘
```

## 必备组件

- `Card`：区域容器
- `Statistic`：统计数值
- `Row` + `Col`：栅格布局
- `DatePicker.RangePicker`（可选）：日期筛选
- 图表组件（如 `@ant-design/charts` 或自定义）
- `Table`（可选）：最近数据
- `List`（可选）：动态/待办

## 代码结构骨架

```tsx
import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Statistic, DatePicker, Table, List, Tag, Spin } from 'antd';
import {
  ArrowUpOutlined,
  ArrowDownOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';

interface DashboardData {
  total: number;
  processing: number;
  completed: number;
  growth: number;
  trend: { date: string; value: number }[];
  categoryStats: { name: string; count: number }[];
  recentItems: any[];
}

const DashboardPage: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<DashboardData | null>(null);
  const [dateRange, setDateRange] = useState<[any, any]>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // const res = await api.getDashboard({ dateRange });
        // setData(res);
      } catch (error) {
        // 错误处理
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [dateRange]);

  if (loading) return <Spin size="large" />;

  return (
    <div style={{ padding: 'var(--content-padding, 24px)' }}>
      {/* 顶部筛选 */}
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
        <h2 style={{ margin: 0 }}>数据概览</h2>
        <DatePicker.RangePicker onChange={(dates) => setDateRange(dates as any)} />
      </div>

      {/* 统计卡片 */}
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={12} sm={12} md={6}>
          <Card>
            <Statistic title="总数" value={data?.total ?? 0} />
          </Card>
        </Col>
        <Col xs={12} sm={12} md={6}>
          <Card>
            <Statistic title="进行中" value={data?.processing ?? 0} />
          </Card>
        </Col>
        <Col xs={12} sm={12} md={6}>
          <Card>
            <Statistic title="已完成" value={data?.completed ?? 0} />
          </Card>
        </Col>
        <Col xs={12} sm={12} md={6}>
          <Card>
            <Statistic
              title="增长率"
              value={data?.growth ?? 0}
              precision={1}
              prefix={data && data.growth >= 0 ? <ArrowUpOutlined /> : <ArrowDownOutlined />}
              suffix="%"
              valueStyle={{ color: data && data.growth >= 0 ? '#3f8600' : '#cf1322' }}
            />
          </Card>
        </Col>
      </Row>

      {/* 图表区域 */}
      <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
        <Col xs={24} lg={16}>
          <Card title="趋势图">
            {/* 图表组件：使用 @ant-design/charts 或自定义 */}
            <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#999' }}>
              趋势图区域
            </div>
          </Card>
        </Col>
        <Col xs={24} lg={8}>
          <Card title="分类统计">
            {/* 饼图或柱状图 */}
            <div style={{ height: 300, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#999' }}>
              分类统计区域
            </div>
          </Card>
        </Col>
      </Row>

      {/* 最近动态 */}
      <Card title="最近动态">
        <List
          dataSource={data?.recentItems ?? []}
          renderItem={(item) => (
            <List.Item>
              {/* 动态项渲染 */}
            </List.Item>
          )}
        />
      </Card>
    </div>
  );
};

export default DashboardPage;
```

# 详情页模板

## 页面结构

```
┌─────────────────────────────────────────────┐
│ 道路 > 某某 > 详情                           │
├─────────────────────────────────────────────┤
│ ← 返回  页面标题             编辑 删除 按钮 │
├─────────────────────────────────────────────┤
│ ┌─────────────────────────────────────────┐ │
│ │ 基本信息                                │ │
│ │ ┌──────────┬──────────────────────────┐ │ │
│ │ │ 字段名   │ 值                       │ │ │
│ │ │ 字段名   │ 值                       │ │ │
│ │ │ 字段名   │ 值                       │ │ │
│ │ └──────────┴──────────────────────────┘ │ │
│ └─────────────────────────────────────────┘ │
│                                             │
│ ┌─────────────────────────────────────────┐ │
│ │ 关联信息（可选）                        │ │
│ │ 表格/标签列表                           │ │
│ └─────────────────────────────────────────┘ │
│                                             │
│ ┌─────────────────────────────────────────┐ │
│ │ 操作记录（可选）                        │ │
│ │ 时间线                                  │ │
│ └─────────────────────────────────────────┘ │
└─────────────────────────────────────────────┘
```

## 必备组件

- `PageContainer` 或自定义面包屑
- `Card`：信息分组容器
- `Descriptions`：键值对信息展示
- `Button`：操作按钮
- `Tag`：状态展示
- `Timeline`（可选）：操作记录
- `Table`（可选）：关联数据

## 代码结构骨架

```tsx
import React, { useState, useEffect } from 'react';
import { Card, Descriptions, Button, Space, Tag, message, Modal, Spin } from 'antd';
import { useNavigate, useParams } from 'react-router-dom';

interface DetailData {
  id: string | number;
  status: string;
  createdAt: string;
  updatedAt: string;
  // 业务字段
}

const EntityDetailPage: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();

  const [loading, setLoading] = useState(true);
  const [detail, setDetail] = useState<DetailData | null>(null);

  // 获取详情
  useEffect(() => {
    const fetchDetail = async () => {
      try {
        // const res = await api.getDetail(id);
        // setDetail(res);
      } catch (error) {
        message.error('获取详情失败');
      } finally {
        setLoading(false);
      }
    };
    fetchDetail();
  }, [id]);

  // 删除
  const handleDelete = () => {
    Modal.confirm({
      title: '确认删除',
      content: '确定要删除吗？此操作不可恢复。',
      okText: '确认删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        // await api.delete(id);
        message.success('删除成功');
        navigate(-1);
      },
    });
  };

  if (loading) return <Spin size="large" />;
  if (!detail) return null;

  return (
    <div style={{ padding: 'var(--content-padding, 24px)' }}>
      {/* 顶部操作栏 */}
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
        <Button onClick={() => navigate(-1)}>返回</Button>
        <Space>
          <Button type="primary">编辑</Button>
          <Button danger onClick={handleDelete}>删除</Button>
        </Space>
      </div>

      {/* 基本信息 */}
      <Card title="基本信息" style={{ marginBottom: 16 }}>
        <Descriptions column={2} bordered>
          <Descriptions.Item label="名称">{/* detail.name */}</Descriptions.Item>
          <Descriptions.Item label="状态">
            <Tag color="blue">{/* detail.status */}</Tag>
          </Descriptions.Item>
          <Descriptions.Item label="创建时间">{/* detail.createdAt */}</Descriptions.Item>
          <Descriptions.Item label="更新时间">{/* detail.updatedAt */}</Descriptions.Item>
        </Descriptions>
      </Card>

      {/* 关联信息（按需） */}
      <Card title="关联信息" style={{ marginBottom: 16 }}>
        {/* Table 或其他内容 */}
      </Card>
    </div>
  );
};

export default EntityDetailPage;
```

# 表单页模板

## 页面结构

```
┌─────────────────────────────────────────────┐
│ 面包屑                                       │
├─────────────────────────────────────────────┤
│ ← 返回  新建/编辑 XXX                        │
├─────────────────────────────────────────────┤
│ ┌─────────────────────────────────────────┐ │
│ │ 基本信息                                │ │
│ │ ┌──────────┬──────────────────────────┐ │ │
│ │ │ 名称 *   │ [输入框]                 │ │ │
│ │ │ 类型 *   │ [下拉选择]               │ │ │
│ │ │ 描述     │ [文本域]                 │ │ │
│ │ └──────────┴──────────────────────────┘ │ │
│ └─────────────────────────────────────────┘ │
│                                             │
│ ┌─────────────────────────────────────────┐ │
│ │ 其他信息（可选分组）                    │ │
│ │ ...                                     │ │
│ └─────────────────────────────────────────┘ │
│                                             │
│                    [取消]  [提交]            │
└─────────────────────────────────────────────┘
```

## 必备组件

- `PageContainer` 或自定义面包屑
- `Card`：表单分组容器
- `Form`：表单
- `Input` / `Input.TextArea`：文本输入
- `Select`：下拉选择
- `DatePicker`：日期选择
- `Switch`：开关
- `Radio.Group`：单选
- `Checkbox.Group`：多选
- `Button`：提交/取消
- `Row` + `Col`：栅格布局

## 代码结构骨架

```tsx
import React, { useEffect } from 'react';
import {
  Card, Form, Input, Select, DatePicker, Switch,
  Button, Space, Row, Col, message,
} from 'antd';
import { useNavigate, useParams } from 'react-router-dom';

interface FormValues {
  name: string;
  type: string;
  description?: string;
  // 业务字段
}

const EntityFormPage: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const [form] = Form.useForm();
  const isEdit = Boolean(id);

  // 编辑模式：加载数据
  useEffect(() => {
    if (isEdit && id) {
      const fetchDetail = async () => {
        try {
          // const res = await api.getDetail(id);
          // form.setFieldsValue(res);
        } catch (error) {
          message.error('获取数据失败');
        }
      };
      fetchDetail();
    }
  }, [id, isEdit, form]);

  // 提交
  const handleSubmit = async (values: FormValues) => {
    try {
      if (isEdit) {
        // await api.update(id, values);
        message.success('更新成功');
      } else {
        // await api.create(values);
        message.success('创建成功');
      }
      navigate(-1);
    } catch (error) {
      message.error(isEdit ? '更新失败' : '创建失败');
    }
  };

  return (
    <div style={{ padding: 'var(--content-padding, 24px)' }}>
      {/* 顶部操作栏 */}
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 16 }}>
        <Button onClick={() => navigate(-1)}>返回</Button>
      </div>

      <Form
        form={form}
        layout="vertical"
        onFinish={handleSubmit}
      >
        {/* 基本信息 */}
        <Card title="基本信息" style={{ marginBottom: 16 }}>
          <Row gutter={16}>
            <Col xs={24} md={12}>
              <Form.Item
                label="名称"
                name="name"
                rules={[{ required: true, message: '请输入名称' }]}
              >
                <Input placeholder="请输入名称" maxLength={50} showCount />
              </Form.Item>
            </Col>
            <Col xs={24} md={12}>
              <Form.Item
                label="类型"
                name="type"
                rules={[{ required: true, message: '请选择类型' }]}
              >
                <Select placeholder="请选择类型" options={[]} />
              </Form.Item>
            </Col>
            <Col xs={24}>
              <Form.Item label="描述" name="description">
                <Input.TextArea placeholder="请输入描述" rows={4} maxLength={500} showCount />
              </Form.Item>
            </Col>
          </Row>
        </Card>

        {/* 底部操作 */}
        <div style={{ textAlign: 'right' }}>
          <Space>
            <Button onClick={() => navigate(-1)}>取消</Button>
            <Button type="primary" htmlType="submit">
              {isEdit ? '保存' : '创建'}
            </Button>
          </Space>
        </div>
      </Form>
    </div>
  );
};

export default EntityFormPage;
```

