# 统计卡片区模板

## 结构

```
┌──────────┐ ┌──────────┐ ┌──────────┐ ┌──────────┐
│ 📊 总数  │ │ ⏳ 进行中│ │ ✅ 已完成│ │ 📈 增长  │
│  1,128   │ │   326    │ │   678    │ │  12.5%↑  │
│ 较昨日 +8 │ │ 较昨日 -2│ │ 较昨日 +5│ │          │
└──────────┘ └──────────┘ └──────────┘ └──────────┘
```

## 代码骨架

```tsx
import React from 'react';
import { Card, Row, Col, Statistic } from 'antd';
import { ArrowUpOutlined, ArrowDownOutlined } from '@ant-design/icons';

interface StatItem {
  title: string;
  value: number;
  prefix?: React.ReactNode;
  suffix?: string;
  precision?: number;
  trend?: {
    value: number;
    label?: string;
  };
}

interface StatsCardsProps {
  items: StatItem[];
  colSpan?: number; // 每个卡片的栅格数，默认 6（4列）
}

const StatsCards: React.FC<StatsCardsProps> = ({ items, colSpan = 6 }) => {
  return (
    <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
      {items.map((item, index) => (
        <Col key={index} xs={12} sm={12} md={colSpan}>
          <Card>
            <Statistic
              title={item.title}
              value={item.value}
              precision={item.precision}
              prefix={item.prefix}
              suffix={item.suffix}
            />
            {item.trend && (
              <div style={{ marginTop: 8, fontSize: 12 }}>
                <span style={{ color: item.trend.value >= 0 ? '#3f8600' : '#cf1322' }}>
                  {item.trend.value >= 0 ? <ArrowUpOutlined /> : <ArrowDownOutlined />}
                  {' '}{Math.abs(item.trend.value)}%
                </span>
                <span style={{ color: '#999', marginLeft: 4 }}>
                  {item.trend.label ?? '较上期'}
                </span>
              </div>
            )}
          </Card>
        </Col>
      ))}
    </Row>
  );
};

export default StatsCards;
```

## 使用示例

```tsx
const stats = [
  { title: '总数', value: 1128, prefix: <TeamOutlined />, trend: { value: 8.2, label: '较昨日' } },
  { title: '进行中', value: 326, prefix: <ClockCircleOutlined />, trend: { value: -2.1, label: '较昨日' } },
  { title: '已完成', value: 678, prefix: <CheckCircleOutlined />, trend: { value: 5.3, label: '较昨日' } },
  { title: '增长率', value: 12.5, precision: 1, suffix: '%', prefix: <RiseOutlined /> },
];

<StatsCards items={stats} />
```

## 使用规范

- 卡片数量建议 2-4 个（2/3/4 列）
- 标题 4 字以内
- 数值使用千分位分隔
- 增长趋势：绿色↑ 下降，红色↓ 下降
- 可选配置：图标前缀、单位后缀、精度

# 表格区模板

## 结构

```
┌───────────────────────────────────────────────┐
│ 批量操作栏（已选 N 项）[批量删除] [批量导出] │
├───────────────────────────────────────────────┤
│ ☐ | 名称 | 类型 | 状态 | 时间 | 操作        │
│ ──| ──── | ── | ─── | ── | ──              │
│                                              │
│                         共 X 条  < 1 2 3 >   │
└───────────────────────────────────────────────┘
```

## 代码骨架

```tsx
import React, { useState } from 'react';
import { Card, Table, Button, Space, Dropdown, message, Modal } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import type { PaginationProps } from 'antd';

interface TableSectionProps<T extends { id: string | number }> {
  columns: ColumnsType<T>;
  dataSource: T[];
  loading?: boolean;
  total?: number;
  onPaginationChange?: (current: number, pageSize: number) => void;
  onDelete?: (id: T['id']) => void;
  onBatchDelete?: (ids: React.Key[]) => void;
  rowSelection?: object;
}

function TableSection<T extends { id: string | number }>({
  columns,
  dataSource,
  loading = false,
  total = 0,
  onPaginationChange,
  onDelete,
  onBatchDelete,
}: TableSectionProps<T>) {
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

  // 单条删除
  const handleDelete = (record: T) => {
    Modal.confirm({
      title: '确认删除',
      content: `确定要删除吗？此操作不可恢复。`,
      okText: '确认删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: () => onDelete?.(record.id),
    });
  };

  // 批量删除
  const handleBatchDelete = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('请选择要删除的项');
      return;
    }
    Modal.confirm({
      title: '确认批量删除',
      content: `确定要删除选中的 ${selectedRowKeys.length} 项吗？`,
      okText: '确认删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: () => {
        onBatchDelete?.(selectedRowKeys);
        setSelectedRowKeys([]);
      },
    });
  };

  const paginationConfig: PaginationProps = {
    total,
    showSizeChanger: true,
    showQuickJumper: true,
    showTotal: (t) => `共 ${t} 条`,
    onChange: onPaginationChange,
  };

  return (
    <Card>
      {/* 批量操作栏 */}
      {selectedRowKeys.length > 0 && (
        <div style={{ marginBottom: 16 }}>
          <Space>
            <span>已选择 {selectedRowKeys.length} 项</span>
            <Button danger size="small" onClick={handleBatchDelete}>批量删除</Button>
            <Button size="small" onClick={() => setSelectedRowKeys([])}>取消选择</Button>
          </Space>
        </div>
      )}

      <Table
        rowKey="id"
        loading={loading}
        columns={columns}
        dataSource={dataSource}
        pagination={paginationConfig}
        rowSelection={{
          selectedRowKeys,
          onChange: setSelectedRowKeys,
        }}
        scroll={{ x: 'max-content' }}
      />
    </Card>
  );
}

export default TableSection;
```

## 使用规范

- 表格必须配置 `rowKey`
- 大数据量时开启 `scroll={{ x: 'max-content' }}`
- 操作列固定右侧
- 超过 3 个操作使用 Dropdown
- 分页默认展示总数、页码跳转、条数切换

