  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

  // 分页状态
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0,
  });

  // 搜索参数
  const [searchParams, setSearchParams] = useState<Record<string, any>>({});

  // 数据请求
  const fetchData = useCallback(async (params = {}) => {
    setLoading(true);
    try {
      // 请求接口
      // const res = await api.getList({ ...searchParams, ...params });
      // setDataSource(res.list);
      // setPagination(prev => ({ ...prev, total: res.total }));
    } catch (error) {
      message.error('获取数据失败');
    } finally {
      setLoading(false);
    }
  }, [searchParams]);

  // 查询
  const handleSearch = () => {
    const values = searchForm.getFieldsValue();
    setSearchParams(values);
    setPagination(prev => ({ ...prev, current: 1 }));
    fetchData({ ...values, current: 1 });
  };

  // 重置
  const handleReset = () => {
    searchForm.resetFields();
    setSearchParams({});
    setPagination(prev => ({ ...prev, current: 1 }));
    fetchData({ current: 1 });
  };

  // 删除
  const handleDelete = (record: EntityRecord) => {
    Modal.confirm({
      title: '确认删除',
      content: `确定要删除「${record.id}」吗？此操作不可恢复。`,
      okText: '确认删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        // await api.delete(record.id);
        message.success('删除成功');
        fetchData();
      },
    });
  };

  // 表格列定义
  const columns: ColumnsType<EntityRecord> = [
    // { title: '名称', dataIndex: 'name', fixed: 'left' },
