          columns={columns}
          dataSource={dataSource}
          pagination={paginationConfig}
          rowSelection={{ selectedRowKeys, onChange: setSelectedRowKeys }}
          scroll={{ x: 'max-content' }}
        />
      </Card>
    </div>
  );
};

export default EntityListPage;
